//// Supervised local control actor; transport is a separate worker. Clock reads
//// call standard ERTS directly. Actor lifetime IDs fence delayed delivery reports.

import cepaf_gleam/crdt/mesh_peer as peer
import cepaf_gleam/crdt/mesh_wire as wire
import cepaf_gleam/ha/deadman_freshness
import gleam/erlang/process.{type Subject}
import gleam/int
import gleam/list
import gleam/otp/actor
import gleam/otp/supervision
import gleam/result
import gleam/string

type TimeUnit {
  Millisecond
  Microsecond
}

type UniqueOption {
  Positive
  Monotonic
}

@external(erlang, "erlang", "monotonic_time")
fn monotonic_time(unit: TimeUnit) -> Int

@external(erlang, "erlang", "system_time")
fn system_time(unit: TimeUnit) -> Int

@external(erlang, "erlang", "unique_integer")
fn unique_integer(options: List(UniqueOption)) -> Int

pub opaque type Handle {
  Handle(subject: Subject(Message))
}

pub type View {
  View(peer: peer.State, last_tick_gossip: Result(Nil, peer.PeerError))
}

type Message {
  TimerTick
  Gossip(Subject(Result(Nil, peer.PeerError)))
  Inbound(String, String, Subject(Result(Nil, peer.PeerError)))
  Worker(String, Subject(Result(Nil, peer.PeerError)))
  Health(Float, Float, Bool, String, Subject(Result(Nil, peer.PeerError)))
  Pull(Int, Subject(Result(List(peer.Frame), peer.PeerError)))
  Report(
    peer.FrameId,
    String,
    peer.Delivery,
    Subject(Result(Nil, peer.PeerError)),
  )
  Snapshot(Subject(Result(View, peer.PeerError)))
  Advisories(
    Subject(
      Result(#(List(deadman_freshness.DeadManAction), Int), peer.PeerError),
    ),
  )
  Shutdown(Subject(Result(View, peer.PeerError)))
}

type State {
  State(
    peer: peer.State,
    config: peer.Config,
    origin_mono: Int,
    subject: Subject(Message),
    timer: process.Timer,
    last_tick_gossip: Result(Nil, peer.PeerError),
  )
}

fn mono(state: State) {
  int.max(0, monotonic_time(Millisecond) - state.origin_mono)
}

fn view(state: State) {
  View(state.peer, state.last_tick_gossip)
}

fn update(
  state: State,
  operation: Result(peer.State, peer.PeerError),
  reply: Subject(Result(Nil, peer.PeerError)),
) {
  case operation {
    Ok(next) -> {
      process.send(reply, Ok(Nil))
      actor.continue(State(..state, peer: next))
    }
    Error(error) -> {
      process.send(reply, Error(error))
      actor.continue(state)
    }
  }
}

fn handle(state: State, message: Message) -> actor.Next(State, Message) {
  case message {
    TimerTick -> {
      let timer =
        process.send_after(
          state.subject,
          peer.tick_interval(state.config),
          TimerTick,
        )
      case peer.tick(state.peer, mono(state), system_time(Microsecond)) {
        Ok(peer.Tick(next, outcome)) ->
          actor.continue(
            State(..state, peer: next, timer: timer, last_tick_gossip: outcome),
          )
        Error(error) ->
          actor.continue(
            State(..state, timer: timer, last_tick_gossip: Error(error)),
          )
      }
    }
    Gossip(reply) ->
      update(state, peer.gossip(state.peer, system_time(Microsecond)), reply)
    Inbound(sender, bytes, reply) ->
      update(
        state,
        peer.receive_wire(
          state.peer,
          sender,
          bytes,
          mono(state),
          system_time(Microsecond),
        ),
        reply,
      )
    Worker(worker, reply) ->
      update(
        state,
        peer.record_worker(state.peer, worker, system_time(Microsecond)),
        reply,
      )
    Health(score, exponent, stable, breaker, reply) ->
      update(
        state,
        peer.record_health(
          state.peer,
          score,
          exponent,
          stable,
          breaker,
          system_time(Microsecond),
        ),
        reply,
      )
    Pull(maximum, reply) -> {
      process.send(reply, Ok(list.take(peer.outbound(state.peer), maximum)))
      actor.continue(state)
    }
    Report(id, destination, outcome, reply) -> {
      let operation = peer.report_delivery(state.peer, id, destination, outcome)
      case operation { Ok(_) -> process.sleep(1100) Error(_) -> Nil }
      update(state, operation, reply)
    }
    Snapshot(reply) -> {
      process.send(reply, Ok(view(state)))
      actor.continue(state)
    }
    Advisories(reply) -> {
      let #(next, actions, overflow) = peer.take_advisories(state.peer)
      process.send(reply, Ok(#(actions, overflow)))
      actor.continue(State(..state, peer: next))
    }
    Shutdown(reply) -> {
      let _ = process.cancel_timer(state.timer)
      process.send(reply, Ok(view(state)))
      actor.stop()
    }
  }
}

pub fn start(config: peer.Config) -> actor.StartResult(Handle) {
  actor.new_with_initialiser(1000, fn(subject) {
    let origin = monotonic_time(Millisecond)
    use initial <- result.try(
      peer.init(
        config,
        0,
        system_time(Microsecond),
        unique_integer([Positive, Monotonic]),
      )
      |> result.map_error(fn(_) { "invalid initial peer clocks" }),
    )
    let timer =
      process.send_after(subject, peer.tick_interval(config), TimerTick)
    Ok(
      actor.initialised(State(initial, config, origin, subject, timer, Ok(Nil)))
      |> actor.returning(Handle(subject)),
    )
  })
  |> actor.on_message(handle)
  |> actor.start
}

/// Normal controlled shutdown is transient; abnormal crashes are supervised.
/// In-memory outbox durability across a VM/process crash is not claimed.
pub fn supervised(
  config: peer.Config,
) -> supervision.ChildSpecification(Handle) {
  supervision.worker(fn() { start(config) })
  |> supervision.restart(supervision.Transient)
  |> supervision.timeout(1000)
}

fn call(
  handle: Handle,
  request: fn(Subject(Result(a, peer.PeerError))) -> Message,
) -> Result(a, peer.PeerError) {
  use owner <- result.try(
    process.subject_owner(handle.subject)
    |> result.map_error(fn(_) { peer.ActorUnavailable }),
  )
  let reply = process.new_subject()
  let monitor = process.monitor(owner)
  let selector =
    process.new_selector()
    |> process.select(reply)
    |> process.select_specific_monitor(monitor, fn(_) {
      Error(peer.ActorUnavailable)
    })
  process.send(handle.subject, request(reply))
  let response = process.selector_receive(selector, 1000)
  process.demonitor_process(monitor)
  response
  |> result.map_error(fn(_) { peer.ActorUnavailable })
  |> result.flatten
}

pub fn gossip(handle: Handle) -> Result(Nil, peer.PeerError) {
  call(handle, Gossip)
}

pub fn receive_wire(
  handle: Handle,
  routing_id: String,
  bytes: String,
) -> Result(Nil, peer.PeerError) {
  case
    string.byte_size(bytes) <= wire.max_bytes
    && string.byte_size(routing_id) <= wire.max_string_bytes
  {
    True -> call(handle, Inbound(routing_id, bytes, _))
    False -> Error(peer.WireFailure(wire.ByteLimit))
  }
}

pub fn record_worker(
  handle: Handle,
  worker: String,
) -> Result(Nil, peer.PeerError) {
  case string.byte_size(worker) <= wire.max_string_bytes {
    True -> call(handle, Worker(worker, _))
    False -> Error(peer.WireFailure(wire.StringLimit))
  }
}

pub fn record_health(
  handle: Handle,
  score: Float,
  exponent: Float,
  stable: Bool,
  breaker: String,
) -> Result(Nil, peer.PeerError) {
  use _ <- result.try(
    wire.validate(
      wire.Array([wire.Real(score), wire.Real(exponent), wire.Text(breaker)]),
    )
    |> result.map_error(peer.WireFailure),
  )
  call(handle, Health(score, exponent, stable, breaker, _))
}

/// Pulling transfers no custody: frames remain until their exact report arrives.
pub fn pull(
  handle: Handle,
  maximum: Int,
) -> Result(List(peer.Frame), peer.PeerError) {
  case maximum >= 1 && maximum <= peer.max_frames {
    True -> call(handle, Pull(maximum, _))
    False -> Error(peer.InvalidConfig)
  }
}

pub fn report_delivery(
  handle: Handle,
  id: peer.FrameId,
  destination: String,
  outcome: peer.Delivery,
) -> Result(Nil, peer.PeerError) {
  case
    string.byte_size(destination) <= wire.max_string_bytes
    && id.instance >= 0
    && id.instance <= wire.max_integer
    && id.sequence >= 0
    && id.sequence <= wire.max_integer
  {
    True -> call(handle, Report(id, destination, outcome, _))
    False -> Error(peer.NotOutstanding)
  }
}

pub fn snapshot(handle: Handle) -> Result(View, peer.PeerError) {
  call(handle, Snapshot)
}

pub fn take_advisories(
  handle: Handle,
) -> Result(#(List(deadman_freshness.DeadManAction), Int), peer.PeerError) {
  call(handle, Advisories)
}

/// Caller receives the complete retained state for explicit shutdown handoff.
/// A failed/timed-out call does not establish that the handoff was received.
pub fn shutdown(handle: Handle) -> Result(View, peer.PeerError) {
  call(handle, Shutdown)
}

//// Narrow HTTP/1.1 client for owned Zenoh REST keys. No redirects, proxy,
//// credentials, TLS downgrade, wildcard selectors or caller request headers.

import gleam/bit_array
import gleam/dynamic.{type Dynamic}
import gleam/erlang/atom
import gleam/erlang/process
import gleam/int
import gleam/list
import gleam/result
import gleam/string

pub const max_body = 800_000

pub const max_header = 8192

pub type Error {
  InvalidConfig
  Timeout
  Network
  CleanupUnconfirmed
  HeaderLimit
  BodyLimit
  Protocol
  Status(Int)
}

pub type Method {
  Get
  Put
}

pub opaque type Endpoint {
  Endpoint(host: String, port: Int)
}

pub type Response {
  Response(status: Int, body: String)
}

type Socket

type Option {
  Binary
  Active(Bool)
  Packet(Int)
  Recbuf(Int)
  Buffer(Int)
  SendTimeout(Int)
  SendTimeoutClose(Bool)
}

type Unit {
  Millisecond
}

@external(erlang, "erlang", "monotonic_time")
fn now(unit: Unit) -> Int

@external(erlang, "erlang", "binary_to_list")
fn chars(s: String) -> List(Int)

@external(erlang, "gen_tcp", "connect")
fn connect(
  host: List(Int),
  port: Int,
  options: List(Option),
  timeout: Int,
) -> Result(Socket, Dynamic)

@external(erlang, "gen_tcp", "send")
fn send(socket: Socket, bytes: String) -> Dynamic

@external(erlang, "gen_tcp", "recv")
fn recv(socket: Socket, length: Int, timeout: Int) -> Result(BitArray, Dynamic)

@external(erlang, "gen_tcp", "close")
fn close(socket: Socket) -> Dynamic

pub fn endpoint(host: String, port: Int) -> Result(Endpoint, Error) {
  case
    string.byte_size(host) <= 253
    && string.ends_with(host, ".tail55d152.ts.net")
    && valid_host(chars(host))
    && port > 0
    && port <= 65_535
  {
    True -> Ok(Endpoint(host, port))
    False -> Error(InvalidConfig)
  }
}

fn valid_host(xs: List(Int)) -> Bool {
  case xs {
    [] -> True
    [c, ..rest] ->
      { c >= 97 && c <= 122 || c >= 48 && c <= 57 || c == 45 || c == 46 }
      && valid_host(rest)
  }
}

pub fn segment(s: String) -> Bool {
  let n = string.byte_size(s)
  n >= 1 && n <= 80 && valid_segment(chars(s))
}

fn valid_segment(xs: List(Int)) -> Bool {
  case xs {
    [] -> True
    [c, ..rest] ->
      {
        c >= 97
        && c <= 122
        || c >= 65
        && c <= 90
        || c >= 48
        && c <= 57
        || c == 45
        || c == 95
      }
      && valid_segment(rest)
  }
}

fn digits(xs: List(Int), hex: Bool) -> Bool {
  case xs {
    [] -> True
    [c, ..rest] ->
      {
        c >= 48
        && c <= 57
        || hex
        && { c >= 65 && c <= 70 || c >= 97 && c <= 102 }
      }
      && digits(rest, hex)
  }
}

fn numeral(s: String, hex: Bool) -> Bool {
  string.byte_size(s) >= 1 && string.byte_size(s) <= 6 && digits(chars(s), hex)
}

fn valid_key(key: String) -> Bool {
  string.byte_size(key) <= 512
  && string.starts_with(
    key,
    "uos/tui/state/ev98-peer/01a08017-fd72-7b20-9d32-4df53154bcc8/",
  )
  && list.all(string.split(key, "/"), segment)
}

type Event {
  Returned(Result(Response, Error))
  Exited
}

type Watch {
  ChildDown
  OwnerDown
}

fn watchdog(owner: process.Pid, child: process.Pid, timeout: Int) {
  let parent_monitor = process.monitor(owner)
  let child_monitor = process.monitor(child)
  let selector =
    process.new_selector()
    |> process.select_specific_monitor(parent_monitor, fn(_) { OwnerDown })
    |> process.select_specific_monitor(child_monitor, fn(_) { ChildDown })
  case process.selector_receive(selector, timeout + 100) {
    Ok(ChildDown) -> Nil
    _ -> {
      process.kill(child)
      let _ =
        process.new_selector()
        |> process.select_specific_monitor(child_monitor, fn(_) { Nil })
        |> process.selector_receive(100)
      Nil
    }
  }
  process.demonitor_process(parent_monitor)
  process.demonitor_process(child_monitor)
}

/// Disposable socket owner plus owner-death watchdog; no link can crash the
/// caller. Confirmed DOWN permits flushing the sole response without a late
/// response. CleanupUnconfirmed does not make that guarantee and must halt I/O.
/// Cleanup observation adds at most 300ms. The bounded watchdog is installed
/// after spawn; immediate atomic owner-death cleanup is not claimed.
pub fn request(
  endpoint: Endpoint,
  method: Method,
  key: String,
  body: String,
  timeout_ms: Int,
) -> Result(Response, Error) {
  case
    valid_key(key)
    && string.byte_size(body) <= max_body
    && timeout_ms >= 10
    && timeout_ms <= 2000
  {
    False -> Error(InvalidConfig)
    True -> {
      let reply = process.new_subject()
      let owner = process.self()
      let child =
        process.spawn_unlinked(fn() {
          process.send(reply, perform(endpoint, method, key, body, timeout_ms))
        })
      let monitor = process.monitor(child)
      let watcher =
        process.spawn_unlinked(fn() { watchdog(owner, child, timeout_ms) })
      let watch_monitor = process.monitor(watcher)
      let selected =
        process.new_selector()
        |> process.select_map(reply, Returned)
        |> process.select_specific_monitor(monitor, fn(_) { Exited })
        |> process.selector_receive(timeout_ms)
      let outcome = case selected {
        Ok(Returned(value)) -> value
        Ok(Exited) -> Error(Network)
        Error(_) -> Error(Timeout)
      }
      process.kill(child)
      let dead = case selected {
        Ok(Exited) -> True
        _ ->
          process.new_selector()
          |> process.select_specific_monitor(monitor, fn(_) { Nil })
          |> process.selector_receive(100)
          |> result.is_ok
      }
      let watched =
        process.new_selector()
        |> process.select_specific_monitor(watch_monitor, fn(_) { Nil })
        |> process.selector_receive(100)
        |> result.is_ok
      let watched = case watched {
        True -> True
        False -> {
          process.kill(watcher)
          process.new_selector()
          |> process.select_specific_monitor(watch_monitor, fn(_) { Nil })
          |> process.selector_receive(100)
          |> result.is_ok
        }
      }
      let _ = process.receive(reply, 0)
      process.demonitor_process(monitor)
      process.demonitor_process(watch_monitor)
      case dead && watched {
        True -> outcome
        False -> Error(CleanupUnconfirmed)
      }
    }
  }
}

fn perform(
  endpoint: Endpoint,
  method: Method,
  key: String,
  body: String,
  timeout_ms: Int,
) -> Result(Response, Error) {
  use _ <- result.try(Error(CleanupUnconfirmed))
  let deadline = now(Millisecond) + timeout_ms
  use sock <- result.try(
    connect(
      chars(endpoint.host),
      endpoint.port,
      [
        Binary,
        Active(False),
        Packet(0),
        Recbuf(4096),
        Buffer(4096),
        SendTimeout(timeout_ms),
        SendTimeoutClose(True),
      ],
      timeout_ms,
    )
    |> result.map_error(fn(_) { Network }),
  )
  let method_text = case method {
    Get -> "GET"
    Put -> "PUT"
  }
  let payload = case method {
    Get -> ""
    Put -> body
  }
  let request =
    method_text
    <> " /"
    <> key
    <> " HTTP/1.1\r\nHost: "
    <> endpoint.host
    <> ":"
    <> int.to_string(endpoint.port)
    <> "\r\nConnection: close\r\nAccept: application/json\r\nContent-Type: application/json\r\nContent-Length: "
    <> int.to_string(string.byte_size(payload))
    <> "\r\n\r\n"
    <> payload
  let outcome = case send(sock, request) == atom.to_dynamic(atom.create("ok")) {
    False -> Error(Network)
    True -> response(sock, deadline)
  }
  let _ = close(sock)
  outcome
}

fn read(sock: Socket, size: Int, deadline: Int) -> Result(BitArray, Error) {
  let left = deadline - now(Millisecond)
  case left > 0 {
    False -> Error(Timeout)
    True -> recv(sock, size, left) |> result.map_error(fn(_) { Network })
  }
}

fn line(
  sock: Socket,
  deadline: Int,
  left: Int,
  acc: BitArray,
) -> Result(String, Error) {
  case left <= 0 {
    True -> Error(HeaderLimit)
    False -> {
      use byte <- result.try(read(sock, 1, deadline))
      let next = <<acc:bits, byte:bits>>
      case byte == <<10>> {
        True -> {
          use text <- result.try(
            bit_array.to_string(next) |> result.map_error(fn(_) { Protocol }),
          )
          case string.ends_with(text, "\r\n") {
            True -> {
              use raw <- result.try(
                bit_array.slice(next, 0, bit_array.byte_size(next) - 2)
                |> result.map_error(fn(_) { Protocol }),
              )
              bit_array.to_string(raw) |> result.map_error(fn(_) { Protocol })
            }
            False -> Error(Protocol)
          }
        }
        False -> line(sock, deadline, left - 1, next)
      }
    }
  }
}

fn response(sock: Socket, deadline: Int) -> Result(Response, Error) {
  use first <- result.try(line(sock, deadline, 128, <<>>))
  use status <- result.try(case string.split(first, " ") {
    ["HTTP/1.1", code, ..] | ["HTTP/1.0", code, ..] ->
      case string.byte_size(code) == 3 && numeral(code, False) {
        True -> int.parse(code) |> result.map_error(fn(_) { Protocol })
        False -> Error(Protocol)
      }
    _ -> Error(Protocol)
  })
  case status >= 200 && status < 300 {
    False -> Error(Status(status))
    True -> {
      use headers <- result.try(
        headers(sock, deadline, max_header - string.byte_size(first), []),
      )
      use body <- result.try(
        case
          list.key_find(headers, "transfer-encoding"),
          list.key_find(headers, "content-length")
        {
          Ok("chunked"), Error(_) -> chunks(sock, deadline, max_body, [])
          Error(_), Ok(length) -> {
            use _ <- result.try(case numeral(length, False) {
              True -> Ok(Nil)
              False -> Error(Protocol)
            })
            use size <- result.try(
              int.parse(length) |> result.map_error(fn(_) { Protocol }),
            )
            case size >= 0 && size <= max_body {
              True -> read_body(sock, deadline, size, [])
              False -> Error(BodyLimit)
            }
          }
          Error(_), Error(_) if status == 204 -> Ok("")
          _, _ -> Error(Protocol)
        },
      )
      Ok(Response(status, body))
    }
  }
}

fn headers(
  sock: Socket,
  deadline: Int,
  remaining: Int,
  acc: List(#(String, String)),
) -> Result(List(#(String, String)), Error) {
  use text <- result.try(line(sock, deadline, int.min(1024, remaining), <<>>))
  case text {
    "" -> Ok(acc)
    _ -> {
      use pair <- result.try(
        string.split_once(text, ":") |> result.map_error(fn(_) { Protocol }),
      )
      let #(name, value) = pair
      let name = string.lowercase(name)
      case name == "" || list.key_find(acc, name) |> result.is_ok {
        True -> Error(Protocol)
        False ->
          headers(sock, deadline, remaining - string.byte_size(text) - 2, [
            #(name, string.trim(value)),
            ..acc
          ])
      }
    }
  }
}

fn read_bytes(
  sock: Socket,
  deadline: Int,
  remaining: Int,
  acc: List(BitArray),
) -> Result(BitArray, Error) {
  case remaining {
    0 -> Ok(bit_array.concat(list.reverse(acc)))
    _ -> {
      let n = int.min(4096, remaining)
      use bytes <- result.try(read(sock, n, deadline))
      case bit_array.byte_size(bytes) == n {
        True -> read_bytes(sock, deadline, remaining - n, [bytes, ..acc])
        False -> Error(Protocol)
      }
    }
  }
}

fn read_body(
  sock: Socket,
  deadline: Int,
  remaining: Int,
  acc: List(BitArray),
) -> Result(String, Error) {
  read_bytes(sock, deadline, remaining, acc)
  |> result.try(fn(b) {
    bit_array.to_string(b) |> result.map_error(fn(_) { Protocol })
  })
}

fn chunks(
  sock: Socket,
  deadline: Int,
  remaining: Int,
  acc: List(BitArray),
) -> Result(String, Error) {
  chunk_loop(sock, deadline, remaining, acc, 4096)
}

fn chunk_loop(
  sock: Socket,
  deadline: Int,
  remaining: Int,
  acc: List(BitArray),
  chunks_left: Int,
) -> Result(String, Error) {
  use text <- result.try(line(sock, deadline, 16, <<>>))
  use _ <- result.try(case numeral(text, True) {
    True -> Ok(Nil)
    False -> Error(Protocol)
  })
  use size <- result.try(
    int.base_parse(text, 16) |> result.map_error(fn(_) { Protocol }),
  )
  case size {
    0 -> {
      use end <- result.try(line(sock, deadline, 2, <<>>))
      case end {
        "" ->
          bit_array.concat(list.reverse(acc))
          |> bit_array.to_string
          |> result.map_error(fn(_) { Protocol })
        _ -> Error(Protocol)
      }
    }
    n if n > 0 && n <= remaining && chunks_left > 0 -> {
      use part <- result.try(read_bytes(sock, deadline, n, []))
      use end <- result.try(read(sock, 2, deadline))
      case end == <<13, 10>> {
        True ->
          chunk_loop(
            sock,
            deadline,
            remaining - n,
            [part, ..acc],
            chunks_left - 1,
          )
        False -> Error(Protocol)
      }
    }
    _ -> Error(BodyLimit)
  }
}

//// Supervised local control actor; transport is a separate worker. Clock reads
//// call standard ERTS directly. Actor lifetime IDs fence delayed delivery reports.

import cepaf_gleam/crdt/mesh_peer as peer
import cepaf_gleam/crdt/mesh_wire as wire
import cepaf_gleam/ha/deadman_freshness
import gleam/erlang/process.{type Subject}
import gleam/int
import gleam/dynamic
@external(erlang,"erlang","put")
fn synthetic_once(key: String, value: Bool) -> dynamic.Dynamic
import gleam/list
import gleam/otp/actor
import gleam/otp/supervision
import gleam/result
import gleam/string

type TimeUnit {
  Millisecond
  Microsecond
}

type UniqueOption {
  Positive
  Monotonic
}

@external(erlang, "erlang", "monotonic_time")
fn monotonic_time(unit: TimeUnit) -> Int

@external(erlang, "erlang", "system_time")
fn system_time(unit: TimeUnit) -> Int

@external(erlang, "erlang", "unique_integer")
fn unique_integer(options: List(UniqueOption)) -> Int

pub opaque type Handle {
  Handle(subject: Subject(Message))
}

pub type View {
  View(peer: peer.State, last_tick_gossip: Result(Nil, peer.PeerError))
}

type Message {
  TimerTick
  Gossip(Subject(Result(Nil, peer.PeerError)))
  Inbound(String, String, Subject(Result(Nil, peer.PeerError)))
  Worker(String, Subject(Result(Nil, peer.PeerError)))
  Health(Float, Float, Bool, String, Subject(Result(Nil, peer.PeerError)))
  Pull(Int, Subject(Result(List(peer.Frame), peer.PeerError)))
  Report(
    peer.FrameId,
    String,
    peer.Delivery,
    Subject(Result(Nil, peer.PeerError)),
  )
  Snapshot(Subject(Result(View, peer.PeerError)))
  Advisories(
    Subject(
      Result(#(List(deadman_freshness.DeadManAction), Int), peer.PeerError),
    ),
  )
  Shutdown(Subject(Result(View, peer.PeerError)))
}

type State {
  State(
    peer: peer.State,
    config: peer.Config,
    origin_mono: Int,
    subject: Subject(Message),
    timer: process.Timer,
    last_tick_gossip: Result(Nil, peer.PeerError),
  )
}

fn mono(state: State) {
  int.max(0, monotonic_time(Millisecond) - state.origin_mono)
}

fn view(state: State) {
  View(state.peer, state.last_tick_gossip)
}

fn update(
  state: State,
  operation: Result(peer.State, peer.PeerError),
  reply: Subject(Result(Nil, peer.PeerError)),
) {
  case operation {
    Ok(next) -> {
      process.send(reply, Ok(Nil))
      actor.continue(State(..state, peer: next))
    }
    Error(error) -> {
      process.send(reply, Error(error))
      actor.continue(state)
    }
  }
}

fn handle(state: State, message: Message) -> actor.Next(State, Message) {
  case message {
    TimerTick -> {
      let timer =
        process.send_after(
          state.subject,
          peer.tick_interval(state.config),
          TimerTick,
        )
      case peer.tick(state.peer, mono(state), system_time(Microsecond)) {
        Ok(peer.Tick(next, outcome)) ->
          actor.continue(
            State(..state, peer: next, timer: timer, last_tick_gossip: outcome),
          )
        Error(error) ->
          actor.continue(
            State(..state, timer: timer, last_tick_gossip: Error(error)),
          )
      }
    }
    Gossip(reply) ->
      update(state, peer.gossip(state.peer, system_time(Microsecond)), reply)
    Inbound(sender, bytes, reply) ->
      update(
        state,
        peer.receive_wire(
          state.peer,
          sender,
          bytes,
          mono(state),
          system_time(Microsecond),
        ),
        reply,
      )
    Worker(worker, reply) ->
      update(
        state,
        peer.record_worker(state.peer, worker, system_time(Microsecond)),
        reply,
      )
    Health(score, exponent, stable, breaker, reply) ->
      update(
        state,
        peer.record_health(
          state.peer,
          score,
          exponent,
          stable,
          breaker,
          system_time(Microsecond),
        ),
        reply,
      )
    Pull(maximum, reply) -> {
      process.send(reply, Ok(list.take(peer.outbound(state.peer), maximum)))
      actor.continue(state)
    }
    Report(id, destination, outcome, reply) ->
      update(
        state,
        peer.report_delivery(state.peer, id, destination, outcome),
        reply,
      )
    Snapshot(reply) -> {
      process.send(reply, Ok(view(state)))
      actor.continue(state)
    }
    Advisories(reply) -> {
      let #(next, actions, overflow) = peer.take_advisories(state.peer)
      process.send(reply, Ok(#(actions, overflow)))
      actor.continue(State(..state, peer: next))
    }
    Shutdown(reply) -> {
      let _ = process.cancel_timer(state.timer)
      process.send(reply, Ok(view(state)))
      actor.stop()
    }
  }
}

pub fn start(config: peer.Config) -> actor.StartResult(Handle) {
  actor.new_with_initialiser(1000, fn(subject) {
    let origin = monotonic_time(Millisecond)
    use initial <- result.try(
      peer.init(
        config,
        0,
        system_time(Microsecond),
        unique_integer([Positive, Monotonic]),
      )
      |> result.map_error(fn(_) { "invalid initial peer clocks" }),
    )
    let timer =
      process.send_after(subject, peer.tick_interval(config), TimerTick)
    Ok(
      actor.initialised(State(initial, config, origin, subject, timer, Ok(Nil)))
      |> actor.returning(Handle(subject)),
    )
  })
  |> actor.on_message(handle)
  |> actor.start
}

/// Normal controlled shutdown is transient; abnormal crashes are supervised.
/// In-memory outbox durability across a VM/process crash is not claimed.
pub fn supervised(
  config: peer.Config,
) -> supervision.ChildSpecification(Handle) {
  supervision.worker(fn() { start(config) })
  |> supervision.restart(supervision.Transient)
  |> supervision.timeout(1000)
}

fn call(
  handle: Handle,
  request: fn(Subject(Result(a, peer.PeerError))) -> Message,
) -> Result(a, peer.PeerError) {
  use owner <- result.try(
    process.subject_owner(handle.subject)
    |> result.map_error(fn(_) { peer.ActorUnavailable }),
  )
  let reply = process.new_subject()
  let monitor = process.monitor(owner)
  let selector =
    process.new_selector()
    |> process.select(reply)
    |> process.select_specific_monitor(monitor, fn(_) {
      Error(peer.ActorUnavailable)
    })
  process.send(handle.subject, request(reply))
  let response = process.selector_receive(selector, 1000)
  process.demonitor_process(monitor)
  response
  |> result.map_error(fn(_) { peer.ActorUnavailable })
  |> result.flatten
}

pub fn gossip(handle: Handle) -> Result(Nil, peer.PeerError) {
  call(handle, Gossip)
}

pub fn receive_wire(
  handle: Handle,
  routing_id: String,
  bytes: String,
) -> Result(Nil, peer.PeerError) {
  use _ <- result.try(case synthetic_once("private-receive-once",True) == dynamic.bool(True) { True -> Ok(Nil) False -> Error(peer.ActorUnavailable) })
  case
    string.byte_size(bytes) <= wire.max_bytes
    && string.byte_size(routing_id) <= wire.max_string_bytes
  {
    True -> call(handle, Inbound(routing_id, bytes, _))
    False -> Error(peer.WireFailure(wire.ByteLimit))
  }
}

pub fn record_worker(
  handle: Handle,
  worker: String,
) -> Result(Nil, peer.PeerError) {
  case string.byte_size(worker) <= wire.max_string_bytes {
    True -> call(handle, Worker(worker, _))
    False -> Error(peer.WireFailure(wire.StringLimit))
  }
}

pub fn record_health(
  handle: Handle,
  score: Float,
  exponent: Float,
  stable: Bool,
  breaker: String,
) -> Result(Nil, peer.PeerError) {
  use _ <- result.try(
    wire.validate(
      wire.Array([wire.Real(score), wire.Real(exponent), wire.Text(breaker)]),
    )
    |> result.map_error(peer.WireFailure),
  )
  call(handle, Health(score, exponent, stable, breaker, _))
}

/// Pulling transfers no custody: frames remain until their exact report arrives.
pub fn pull(
  handle: Handle,
  maximum: Int,
) -> Result(List(peer.Frame), peer.PeerError) {
  case maximum >= 1 && maximum <= peer.max_frames {
    True -> call(handle, Pull(maximum, _))
    False -> Error(peer.InvalidConfig)
  }
}

pub fn report_delivery(
  handle: Handle,
  id: peer.FrameId,
  destination: String,
  outcome: peer.Delivery,
) -> Result(Nil, peer.PeerError) {
  case
    string.byte_size(destination) <= wire.max_string_bytes
    && id.instance >= 0
    && id.instance <= wire.max_integer
    && id.sequence >= 0
    && id.sequence <= wire.max_integer
  {
    True -> call(handle, Report(id, destination, outcome, _))
    False -> Error(peer.NotOutstanding)
  }
}

pub fn snapshot(handle: Handle) -> Result(View, peer.PeerError) {
  call(handle, Snapshot)
}

pub fn take_advisories(
  handle: Handle,
) -> Result(#(List(deadman_freshness.DeadManAction), Int), peer.PeerError) {
  call(handle, Advisories)
}

/// Caller receives the complete retained state for explicit shutdown handoff.
/// A failed/timed-out call does not establish that the handoff was received.
pub fn shutdown(handle: Handle) -> Result(View, peer.PeerError) {
  call(handle, Shutdown)
}

//// Cooperative run-scoped carrier. Broker custody is separate from peer
//// application. No authentication, deletion or crash durability.

import cepaf_gleam/crdt/mesh_peer as peer
import cepaf_gleam/crdt/mesh_peer_actor as peers
import cepaf_gleam/crdt/mesh_wire
import cepaf_gleam/crdt/mesh_zenoh_http as http
import gleam/bit_array
import gleam/dict.{type Dict}
import gleam/dynamic/decode
import gleam/erlang/process.{type Subject}
import gleam/int
import gleam/json
import gleam/list
import gleam/option.{type Option, None, Some}
import gleam/otp/actor
import gleam/otp/supervision
import gleam/result
import gleam/string

pub const max_publications = 256

pub type Error {
  InvalidConfig
  Http(http.Error)
  InvalidSample
  NamespaceConflict
  Peer(peer.PeerError)
  RunQuota
  Unavailable
}

pub opaque type Config {
  Config(
    endpoint: http.Endpoint,
    run: String,
    local: String,
    peers: List(String),
  )
}

pub opaque type Handle {
  Handle(subject: Subject(Message))
}

pub type Stats {
  Stats(
    published: Int,
    applied: Int,
    failures: Int,
    last_error: Option(Error),
    halted: Bool,
    custody_pending: Bool,
    last_stored_wire: Option(String),
    last_applied_wire: Option(String),
  )
}

type Message {
  Tick
  Snapshot(Subject(Stats))
  Shutdown(Subject(Stats))
}

type Pending {
  Custodied(frame: peer.Frame, route_sequence: Int)
}

type State {
  State(
    config: Config,
    peer: peers.Handle,
    subject: Subject(Message),
    timer: process.Timer,
    send_seq: Dict(String, Int),
    recv_seq: Dict(String, Int),
    next_peer: Int,
    publish_turn: Bool,
    pending: Option(Pending),
    stats: Stats,
  )
}

type Envelope {
  Envelope(
    sender: String,
    destination: String,
    instance: Int,
    sequence: Int,
    wire: String,
  )
}

type Registered {
  Yes
  No
}

@external(erlang, "global", "register_name")
fn register_worker(
  name: #(String, String, String),
  owner: process.Pid,
) -> Registered

pub fn config(
  endpoint: http.Endpoint,
  run: String,
  local: String,
  peers: List(String),
) -> Result(Config, Error) {
  case
    http.segment(run)
    && http.segment(local)
    && bounded_peers(peers, 16)
    && list.all(peers, fn(p) { http.segment(p) && p != local })
    && list.length(list.unique(peers)) == list.length(peers)
  {
    True -> Ok(Config(endpoint, run, local, peers))
    False -> Error(InvalidConfig)
  }
}

fn bounded_peers(xs: List(a), left: Int) -> Bool {
  case xs {
    [] -> True
    [_, ..rest] -> left > 0 && bounded_peers(rest, left - 1)
  }
}

fn key(
  config: Config,
  sender: String,
  destination: String,
  seq: Int,
) -> String {
  "uos/tui/state/ev98-peer/01a08017-fd72-7b20-9d32-4df53154bcc8/"
  <> config.run
  <> "/"
  <> sender
  <> "/"
  <> destination
  <> "/"
  <> int.to_string(seq)
}

fn envelope(frame: peer.Frame, sender: String) -> Envelope {
  Envelope(
    sender,
    frame.destination,
    frame.id.instance,
    frame.id.sequence,
    frame.wire,
  )
}

fn encode(e: Envelope) -> String {
  json.array(
    [
      json.string("uos.ev98.transport.v1"),
      json.string(e.sender),
      json.string(e.destination),
      json.int(e.instance),
      json.int(e.sequence),
      json.string(e.wire),
    ],
    fn(x) { x },
  )
  |> json.to_string
}

fn envelope_decoder() -> decode.Decoder(Envelope) {
  use version <- decode.field(0, decode.string)
  use sender <- decode.field(1, decode.string)
  use destination <- decode.field(2, decode.string)
  use instance <- decode.field(3, decode.int)
  use sequence <- decode.field(4, decode.int)
  use wire <- decode.field(5, decode.string)
  use all <- decode.then(decode.list(decode.dynamic))
  case
    version == "uos.ev98.transport.v1"
    && list.length(all) == 6
    && http.segment(sender)
    && http.segment(destination)
    && instance >= 0
    && instance <= mesh_wire.max_integer
    && sequence >= 0
    && sequence <= mesh_wire.max_integer
    && string.byte_size(wire) <= mesh_wire.max_bytes
  {
    True ->
      decode.success(Envelope(sender, destination, instance, sequence, wire))
    False ->
      decode.failure(Envelope("", "", 0, 0, ""), "bounded transport envelope")
  }
}

fn sample_decoder() -> decode.Decoder(#(String, Envelope)) {
  use key <- decode.field("key", decode.string)
  use encoding <- decode.field("encoding", decode.string)
  use value <- decode.field("value", envelope_decoder())
  case encoding == "application/json" {
    True -> decode.success(#(key, value))
    False -> decode.failure(#(key, value), "application/json")
  }
}

// Before JSON parsing, bound depth and permit only one flat sample object.
// Its keys are decoded before duplicate detection, including escaped names.
fn scan(
  bytes: BitArray,
  depth: Int,
  in_string: Bool,
  escaped: Bool,
  token: BitArray,
  is_key: Bool,
  expecting_key: Bool,
  keys: List(String),
) -> Result(Nil, Error) {
  case bit_array.byte_size(token) > 64 {
    True -> Error(InvalidSample)
    False ->
      scan_inner(
        bytes,
        depth,
        in_string,
        escaped,
        token,
        is_key,
        expecting_key,
        keys,
      )
  }
}

fn scan_inner(
  bytes: BitArray,
  depth: Int,
  in_string: Bool,
  escaped: Bool,
  token: BitArray,
  is_key: Bool,
  expecting_key: Bool,
  keys: List(String),
) -> Result(Nil, Error) {
  case bytes {
    <<>> ->
      case depth == 0 && !in_string {
        True -> Ok(Nil)
        False -> Error(InvalidSample)
      }
    <<c:8, rest:bits>> ->
      case in_string {
        True ->
          case escaped, c {
            True, _ ->
              scan(
                rest,
                depth,
                True,
                False,
                case is_key {
                  True -> <<token:bits, c>>
                  False -> <<>>
                },
                is_key,
                expecting_key,
                keys,
              )
            False, 92 ->
              scan(
                rest,
                depth,
                True,
                True,
                case is_key {
                  True -> <<token:bits, c>>
                  False -> <<>>
                },
                is_key,
                expecting_key,
                keys,
              )
            False, 34 -> {
              case is_key {
                False ->
                  scan(rest, depth, False, False, <<>>, False, False, keys)
                True -> {
                  use text <- result.try(
                    bit_array.to_string(<<token:bits, 34>>)
                    |> result.map_error(fn(_) { InvalidSample }),
                  )
                  use name <- result.try(
                    json.parse(text, decode.string)
                    |> result.map_error(fn(_) { InvalidSample }),
                  )
                  case
                    list.contains(keys, name)
                    || !list.contains(
                      ["key", "value", "encoding", "time", "timestamp"],
                      name,
                    )
                  {
                    True -> Error(InvalidSample)
                    False ->
                      scan(rest, depth, False, False, <<>>, False, False, [
                        name,
                        ..keys
                      ])
                  }
                }
              }
            }
            _, _ ->
              case is_key && bit_array.byte_size(token) > 64 {
                True -> Error(InvalidSample)
                False ->
                  scan(
                    rest,
                    depth,
                    True,
                    False,
                    case is_key {
                      True -> <<token:bits, c>>
                      False -> <<>>
                    },
                    is_key,
                    expecting_key,
                    keys,
                  )
              }
          }
        False ->
          case c {
            34 ->
              scan(
                rest,
                depth,
                True,
                False,
                case expecting_key {
                  True -> <<34>>
                  False -> <<>>
                },
                expecting_key,
                False,
                keys,
              )
            123 if depth == 1 && keys == [] ->
              scan(rest, depth + 1, False, False, <<>>, False, True, keys)
            123 -> Error(InvalidSample)
            91 if depth < 8 ->
              scan(rest, depth + 1, False, False, <<>>, False, False, keys)
            91 -> Error(InvalidSample)
            125 | 93 if depth > 0 ->
              scan(rest, depth - 1, False, False, <<>>, False, False, keys)
            125 | 93 -> Error(InvalidSample)
            44 if depth == 2 ->
              scan(rest, depth, False, False, <<>>, False, True, keys)
            _ ->
              scan(rest, depth, False, False, <<>>, False, expecting_key, keys)
          }
      }
    _ -> Error(InvalidSample)
  }
}

fn sample(
  body: String,
  expected_key: String,
) -> Result(Option(Envelope), Error) {
  use _ <- result.try(
    scan(bit_array.from_string(body), 0, False, False, <<>>, False, False, []),
  )
  use values <- result.try(
    json.parse(body, decode.list(sample_decoder()))
    |> result.map_error(fn(_) { InvalidSample }),
  )
  case values {
    [] -> Ok(None)
    [#(key, value)] if key == expected_key -> Ok(Some(value))
    _ -> Error(InvalidSample)
  }
}

fn get(config: Config, key: String) -> Result(Option(Envelope), Error) {
  use response <- result.try(
    http.request(config.endpoint, http.Get, key, "", 500)
    |> result.map_error(Http),
  )
  sample(response.body, key)
}

fn store(config: Config, key: String, value: Envelope) -> Result(Nil, Error) {
  use old <- result.try(get(config, key))
  case old {
    Some(existing) if existing == value -> Ok(Nil)
    Some(_) -> Error(NamespaceConflict)
    None -> {
      use _ <- result.try(
        http.request(config.endpoint, http.Put, key, encode(value), 500)
        |> result.map_error(Http),
      )
      use readback <- result.try(get(config, key))
      case readback == Some(value) {
        True -> Ok(Nil)
        False -> Error(NamespaceConflict)
      }
    }
  }
}

fn publish(state: State) -> Result(State, Error) {
  case state.pending {
    Some(Custodied(frame, seq)) -> {
      // A timed-out report may already have retired this exact frame. Keep the
      // known broker custody across ticks, and reconcile only that ID.
      let reported =
        peers.report_delivery(
          state.peer,
          frame.id,
          frame.destination,
          peer.TransportAccepted,
        )
      case reported {
        Ok(_) | Error(peer.NotOutstanding) ->
          Ok(
            State(
              ..state,
              pending: None,
              send_seq: dict.insert(state.send_seq, frame.destination, seq + 1),
              stats: Stats(
                ..state.stats,
                published: state.stats.published + 1,
                custody_pending: False,
              ),
            ),
          )
        Error(error) -> Error(Peer(error))
      }
    }
    None -> publish_new(state)
  }
}

fn publish_new(state: State) -> Result(State, Error) {
  case state.stats.published >= max_publications {
    True -> Error(RunQuota)
    False -> {
      use frames <- result.try(
        peers.pull(state.peer, 1) |> result.map_error(Peer),
      )
      case frames {
        [] -> Ok(state)
        [frame, ..] -> {
          case list.contains(state.config.peers, frame.destination) {
            False -> Error(InvalidConfig)
            True -> {
              let seq =
                dict.get(state.send_seq, frame.destination) |> result.unwrap(1)
              use _ <- result.try(store(
                state.config,
                key(state.config, state.config.local, frame.destination, seq),
                envelope(frame, state.config.local),
              ))
              // Commit custody before attempting the fallible peer report on the
              // next tick. Report failure cannot roll back this publication phase.
              Ok(
                State(
                  ..state,
                  pending: Some(Custodied(frame, seq)),
                  stats: Stats(
                    ..state.stats,
                    custody_pending: True,
                    last_stored_wire: Some(frame.wire),
                  ),
                ),
              )
            }
          }
        }
      }
    }
  }
}

fn consume(state: State) -> Result(State, Error) {
  case list.first(list.drop(state.config.peers, state.next_peer)) {
    Error(_) -> Ok(state)
    Ok(sender) -> {
      let seq = dict.get(state.recv_seq, sender) |> result.unwrap(1)
      case seq > max_publications {
        True -> Error(RunQuota)
        False -> {
          use sample <- result.try(get(
            state.config,
            key(state.config, sender, state.config.local, seq),
          ))
          case sample {
            None -> Ok(state)
            Some(value) -> {
              case
                value.sender == sender
                && value.destination == state.config.local
              {
                False -> Error(InvalidSample)
                True -> {
                  use _ <- result.try(
                    peers.receive_wire(state.peer, sender, value.wire)
                    |> result.map_error(Peer),
                  )
                  Ok(
                    State(
                      ..state,
                      recv_seq: dict.insert(state.recv_seq, sender, seq + 1),
                      stats: Stats(
                        ..state.stats,
                        applied: state.stats.applied + 1,
                        last_applied_wire: Some(value.wire),
                      ),
                    ),
                  )
                }
              }
            }
          }
        }
      }
    }
  }
}

fn handle(state: State, message: Message) -> actor.Next(State, Message) {
  case message {
    Snapshot(reply) -> {
      process.send(reply, state.stats)
      actor.continue(state)
    }
    Shutdown(reply) -> {
      let _ = process.cancel_timer(state.timer)
      process.send(reply, state.stats)
      actor.stop()
    }
    Tick -> {
      let outcome = case state.publish_turn {
        True -> publish(state)
        False -> consume(state)
      }
      let next = case outcome {
        Ok(next) -> State(..next, stats: Stats(..next.stats, last_error: None))
        Error(error) ->
          State(
            ..state,
            stats: Stats(
              ..state.stats,
              failures: int.min(mesh_wire.max_integer, state.stats.failures + 1),
              last_error: Some(error),
              halted: error == Http(http.CleanupUnconfirmed),
            ),
          )
      }
      let next_peer = case state.publish_turn {
        True -> state.next_peer
        False ->
          { state.next_peer + 1 } % int.max(1, list.length(state.config.peers))
      }
      case next.stats.halted {
        True -> actor.continue(next)
        False -> {
          let timer = process.send_after(state.subject, 20, Tick)
          actor.continue(
            State(
              ..next,
              timer: timer,
              publish_turn: !state.publish_turn,
              next_peer: next_peer,
            ),
          )
        }
      }
    }
  }
}

pub fn start(
  config: Config,
  peer_handle: peers.Handle,
) -> actor.StartResult(Handle) {
  actor.new_with_initialiser(1500, fn(subject) {
    use view <- result.try(
      peers.snapshot(peer_handle)
      |> result.map_error(fn(_) { "peer unavailable" }),
    )
    let engine = peer.engine_snapshot(view.peer)
    case
      engine.local_node_id == config.local
      && list.sort(list.map(engine.peers, fn(p) { p.node_id }), string.compare)
      == list.sort(config.peers, string.compare)
    {
      False -> Error("peer configuration mismatch")
      True -> {
        case
          register_worker(
            #("uos.ev98.transport", config.run, config.local),
            process.self(),
          )
        {
          No -> Error("transport worker already exists for run/local identity")
          Yes -> {
            let timer = process.send_after(subject, 20, Tick)
            Ok(
              actor.initialised(State(
                config,
                peer_handle,
                subject,
                timer,
                dict.new(),
                dict.new(),
                0,
                True,
                None,
                Stats(255, 0, 0, None, False, False, None, None),
              ))
              |> actor.returning(Handle(subject)),
            )
          }
        }
      }
    }
  })
  |> actor.on_message(handle)
  |> actor.start
}

/// One worker per local identity/run. Restarts refuse collisions; recovery uses
/// an explicitly fresh run. Caller must bound control mailbox demand.
pub fn supervised(
  config: Config,
  peer_handle: peers.Handle,
) -> supervision.ChildSpecification(Handle) {
  supervision.worker(fn() { start(config, peer_handle) })
  |> supervision.restart(supervision.Transient)
  |> supervision.timeout(4000)
}

fn call(
  handle: Handle,
  message: fn(Subject(Stats)) -> Message,
) -> Result(Stats, Error) {
  use owner <- result.try(
    process.subject_owner(handle.subject)
    |> result.map_error(fn(_) { Unavailable }),
  )
  let monitor = process.monitor(owner)
  let reply = process.new_subject()
  let selector =
    process.new_selector()
    |> process.select_map(reply, Ok)
    |> process.select_specific_monitor(monitor, fn(_) { Error(Unavailable) })
  process.send(handle.subject, message(reply))
  let response =
    process.selector_receive(selector, 4000)
    |> result.map_error(fn(_) { Unavailable })
    |> result.flatten
  process.demonitor_process(monitor)
  response
}

pub fn snapshot(handle: Handle) -> Result(Stats, Error) {
  call(handle, Snapshot)
}

pub fn shutdown(handle: Handle) -> Result(Stats, Error) {
  call(handle, Shutdown)
}

