//// Narrow HTTP/1.1 client for owned Zenoh REST keys. No redirects, proxy,
//// credentials, TLS downgrade, wildcard selectors or caller request headers.
import gleam/bit_array
import gleam/dynamic.{type Dynamic}
import gleam/erlang/atom
import gleam/erlang/process
import gleam/int
import gleam/list
import gleam/result
import gleam/string

pub const max_body = 800_000
pub const max_header = 8192

pub type Error { InvalidConfig Timeout Network HeaderLimit BodyLimit Protocol Status(Int) }
pub type Method { Get Put }
pub opaque type Endpoint { Endpoint(host: String, port: Int) }
pub type Response { Response(status: Int, body: String) }
type Socket
type Option { Binary Active(Bool) Packet(Int) Recbuf(Int) Buffer(Int) SendTimeout(Int) SendTimeoutClose(Bool) }
type Unit { Millisecond }
@external(erlang, "erlang", "monotonic_time")
fn now(unit: Unit) -> Int
@external(erlang, "erlang", "binary_to_list")
fn chars(s: String) -> List(Int)
@external(erlang, "gen_tcp", "connect")
fn connect(host: List(Int), port: Int, options: List(Option), timeout: Int) -> Result(Socket, Dynamic)
@external(erlang, "gen_tcp", "send")
fn send(socket: Socket, bytes: String) -> Dynamic
@external(erlang, "gen_tcp", "recv")
fn recv(socket: Socket, length: Int, timeout: Int) -> Result(BitArray, Dynamic)
@external(erlang, "gen_tcp", "close")
fn close(socket: Socket) -> Dynamic

pub fn endpoint(host: String, port: Int) -> Result(Endpoint, Error) {
  case string.byte_size(host) <= 253 && string.ends_with(host, ".tail55d152.ts.net")
    && valid_host(chars(host)) && port > 0 && port <= 65535 {
    True -> Ok(Endpoint(host, port))
    False -> Error(InvalidConfig)
  }
}
fn valid_host(xs: List(Int)) -> Bool {
  case xs { [] -> True [c,..rest] -> { c >= 97 && c <= 122 || c >= 48 && c <= 57 || c == 45 || c == 46 } && valid_host(rest) }
}
pub fn segment(s: String) -> Bool {
  let n = string.byte_size(s)
  n >= 1 && n <= 80 && valid_segment(chars(s))
}
fn valid_segment(xs: List(Int)) -> Bool {
  case xs { [] -> True [c,..rest] -> { c >= 97 && c <= 122 || c >= 65 && c <= 90 || c >= 48 && c <= 57 || c == 45 || c == 95 } && valid_segment(rest) }
}
fn valid_key(key: String) -> Bool {
  string.byte_size(key) <= 512
  && string.starts_with(key, "uos/tui/state/ev98-peer/01a08017-fd72-7b20-9d32-4df53154bcc8/")
  && list.all(string.split(key, "/"), segment)
}

/// One linked disposable owner bounds DNS/connect/send/read and closes its
/// socket on exit. The invoking transport actor never runs in the peer actor.
pub fn request(endpoint: Endpoint, method: Method, key: String, body: String, timeout_ms: Int) -> Result(Response, Error) {
  case valid_key(key) && string.byte_size(body) <= max_body && timeout_ms >= 10 && timeout_ms <= 2000 {
    False -> Error(InvalidConfig)
    True -> {
      let reply = process.new_subject()
      let child = process.spawn(fn() { process.send(reply, perform(endpoint, method, key, body, timeout_ms)) })
      let outcome = process.receive(reply, timeout_ms) |> result.map_error(fn(_) { Timeout }) |> result.flatten
      // Unlink before kill: timeout must not kill the caller. A linked owner
      // still ensures caller death cannot leave a request child running.
      process.unlink(child)
      process.kill(child)
      outcome
    }
  }
}
fn perform(endpoint: Endpoint, method: Method, key: String, body: String, timeout_ms: Int) -> Result(Response, Error) {
  let deadline = now(Millisecond) + timeout_ms
  use sock <- result.try(connect(chars(endpoint.host), endpoint.port, [Binary,Active(False),Packet(0),Recbuf(4096),Buffer(4096),SendTimeout(timeout_ms),SendTimeoutClose(True)],timeout_ms) |> result.map_error(fn(_) { Network }))
  let method_text = case method { Get -> "GET" Put -> "PUT" }
  let payload = case method { Get -> "" Put -> body }
  let request = method_text <> " /" <> key <> " HTTP/1.1\r\nHost: " <> endpoint.host <> ":" <> int.to_string(endpoint.port) <> "\r\nConnection: close\r\nAccept: application/json\r\nContent-Type: application/json\r\nContent-Length: " <> int.to_string(string.byte_size(payload)) <> "\r\n\r\n" <> payload
  let outcome = case send(sock, request) == atom.to_dynamic(atom.create("ok")) {
    False -> Error(Network)
    True -> response(sock, deadline)
  }
  let _ = close(sock)
  outcome
}
fn read(sock: Socket, size: Int, deadline: Int) -> Result(BitArray, Error) {
  let left = deadline - now(Millisecond)
  case left > 0 { False -> Error(Timeout) True -> recv(sock,size,left) |> result.map_error(fn(_) { Network }) }
}
fn line(sock: Socket, deadline: Int, left: Int, acc: BitArray) -> Result(String, Error) {
  case left <= 0 { True -> Error(HeaderLimit) False -> {
    use byte <- result.try(read(sock,1,deadline))
    let next = <<acc:bits,byte:bits>>
    case byte == <<10>> {
      True -> {
        use text <- result.try(bit_array.to_string(next) |> result.map_error(fn(_) { Protocol }))
        case string.ends_with(text,"\r\n") { True -> Ok(string.drop_end(text,2)) False -> Error(Protocol) }
      }
      False -> line(sock,deadline,left - 1,next)
    }
  } }
}
fn response(sock: Socket, deadline: Int) -> Result(Response, Error) {
  use first <- result.try(line(sock,deadline,128,<<>>))
  use status <- result.try(case string.split(first," ") {
    ["HTTP/1.1",code,.._] | ["HTTP/1.0",code,.._] -> int.parse(code) |> result.map_error(fn(_) { Protocol })
    _ -> Error(Protocol)
  })
  case status >= 200 && status < 300 { False -> Error(Status(status)) True -> {
    use headers <- result.try(headers(sock,deadline,max_header - string.byte_size(first),[]))
    use body <- result.try(case list.key_find(headers,"transfer-encoding"),list.key_find(headers,"content-length") {
      Ok("chunked"), Error(_) -> chunks(sock,deadline,max_body,[])
      Error(_),Ok(length) -> {
        use size <- result.try(int.parse(length) |> result.map_error(fn(_) { Protocol }))
        case size >= 0 && size <= max_body { True -> read_body(sock,deadline,size,[]) False -> Error(BodyLimit) }
      }
      Error(_),Error(_) if status == 204 -> Ok("")
      _,_ -> Error(Protocol)
    })
    Ok(Response(status,body))
  } }
}
fn headers(sock: Socket, deadline: Int, remaining: Int, acc: List(#(String,String))) -> Result(List(#(String,String)),Error) {
  use text <- result.try(line(sock,deadline,int.min(1024,remaining),<<>>))
  case text {
    "" -> Ok(acc)
    _ -> {
      use pair <- result.try(string.split_once(text,":") |> result.map_error(fn(_) { Protocol }))
      let #(name,value) = pair
      let name = string.lowercase(name)
      case name == "" || list.key_find(acc,name) |> result.is_ok {
        True -> Error(Protocol)
        False -> headers(sock,deadline,remaining - string.byte_size(text) - 2,[#(name,string.trim(value)),..acc])
      }
    }
  }
}
fn read_body(sock: Socket, deadline: Int, remaining: Int, acc: List(BitArray)) -> Result(String,Error) {
  case remaining { 0 -> bit_array.concat(list.reverse(acc)) |> bit_array.to_string |> result.map_error(fn(_) { Protocol }) _ -> {
    let n = int.min(4096,remaining)
    use bytes <- result.try(read(sock,n,deadline))
    case bit_array.byte_size(bytes) == n { True -> read_body(sock,deadline,remaining - n,[bytes,..acc]) False -> Error(Protocol) }
  } }
}
fn chunks(sock: Socket, deadline: Int, remaining: Int, acc: List(String)) -> Result(String,Error) {
  use text <- result.try(line(sock,deadline,16,<<>>))
  use size <- result.try(int.base_parse(text,16) |> result.map_error(fn(_) { Protocol }))
  case size {
    0 -> { use end <- result.try(line(sock,deadline,2,<<>>)) case end { "" -> Ok(string.concat(list.reverse(acc))) _ -> Error(Protocol) } }
    n if n > 0 && n <= remaining -> {
      use part <- result.try(read_body(sock,deadline,n,[]))
      use end <- result.try(read(sock,2,deadline))
      case end == <<13,10>> { True -> chunks(sock,deadline,remaining - n,[part,..acc]) False -> Error(Protocol) }
    }
    _ -> Error(BodyLimit)
  }
}

