fn recv(sock: Socket, n: Int, timeout: Int) -> Result(BitArray,Dynamic)
@external(erlang,"gen_tcp","send")
fn send(sock: Socket, data: String) -> Dynamic
@external(erlang,"gen_tcp","close")
fn close(sock: Socket) -> Dynamic
type Mode { Store FailPut Slow Huge Duplicate Chunked Redirect DeepJson Ambiguous BadChunk ChunkHuge Cleanup(process.Subject(Bool)) RetryReadback(process.Subject(String)) DuplicateJson }
fn read_header(sock: Socket, acc: String, left: Int) -> String {
 case left > 0 { False -> panic as "test request header quota" True -> {
   let assert Ok(b) = recv(sock,1,1000)
   let assert Ok(s) = bit_array.to_string(b)
   let text = acc <> s
   case string.ends_with(text,"\r\n\r\n") { True -> text False -> read_header(sock,text,left - 1) }
 } }
}
fn reply(body: String) -> String { "HTTP/1.1 200 OK\r\nContent-Length: " <> int.to_string(string.byte_size(body)) <> "\r\n\r\n" <> body }
fn serve(socket: Socket, mode: Mode, store: dict.Dict(String,String), left: Int) {
 case left > 0 { False -> Nil True -> {
  case accept(socket,2000) { Error(_) -> Nil Ok(client) -> {
   let header = read_header(client,"",8192)
   let lines = string.split(header,"\r\n")
   let assert Ok(first) = list.first(lines)
   let assert [method,path,.._] = string.split(first," ")
   let length = lines |> list.find_map(fn(line) {
    case string.split_once(line,": ") { Ok(#("Content-Length",n)) -> int.parse(n) _ -> Error(Nil) }
   }) |> result.unwrap(0)
   let body = case length { 0 -> "" _ -> { let assert Ok(b) = recv(client,length,1000) let assert Ok(text) = bit_array.to_string(b) text } }
   let #(output,next) = case mode {
    Slow -> { process.sleep(150) #(reply("[]"),store) }
    Huge -> #("HTTP/1.1 200 OK\r\nContent-Length: 800001\r\n\r\n",store)
    Duplicate -> #("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nContent-Length: 2\r\n\r\n[]",store)
    Chunked -> #("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n1\r\n[\r\n1\r\n]\r\n0\r\n\r\n",store)
    Redirect -> #("HTTP/1.1 302 Found\r\nLocation: http://example.com/\r\nContent-Length: 0\r\n\r\n",store)
    DeepJson -> #(reply(string.repeat("[",30) <> string.repeat("]",30)),store)
    Ambiguous -> #("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nTransfer-Encoding: chunked\r\n\r\n[]",store)
    BadChunk -> #("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n2\r\n[]XX0\r\n\r\n",store)
    ChunkHuge -> #("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\nc3501\r\n",store)
    Cleanup(observer) -> {
      let outcome = recv(client,1,1000)
      let closed = case outcome { Error(reason) -> reason == atom.to_dynamic(atom.create("closed")) _ -> False }
      process.send(observer,closed)
      #("",store)
    }
    DuplicateJson -> #(reply("[{\"key\":\"wrong\",\"key\":\"wrong2\",\"encoding\":\"application/json\",\"value\":[]}]"),store)
    FailPut if method == "PUT" -> #("HTTP/1.1 503 unavailable\r\nContent-Length: 0\r\n\r\n",store)
    _ -> case method {
     "PUT" -> {
       case mode { RetryReadback(observer) -> process.send(observer,"PUT") _ -> Nil }
       #(reply(""),dict.insert(store,path,body))
     }
     _ -> {
       let sample = case dict.get(store,path) {
        Error(_) -> "[]"
        Ok(value) -> "[{\"key\":" <> json.to_string(json.string(string.drop_start(path,1))) <> ",\"encoding\":\"application/json\",\"value\":" <> value <> "}]"
       }
       case mode, dict.get(store,"__held") {
         RetryReadback(observer),Error(_) if sample != "[]" -> {
           process.send(observer,"READBACK_LOST")
           #(reply("[]"),dict.insert(store,"__held","true"))
         }
         _,_ -> #(reply(sample),store)
       }
     }
    }
   }
   let _ = send(client,output)
   let _ = close(client)
   serve(socket,mode,next,left - 1)
  } }
 } }
}
fn server(mode: Mode) -> #(process.Pid,Int) {
 let reply = process.new_subject()
 let pid = process.spawn(fn() {
  let assert Ok(sock) = listen(0,[Binary,Active(False),Packet(0),Reuseaddr(True),Ip(#(100,87,7,78))])
  let assert Ok(port) = port(sock)
  process.send(reply,port)
  serve(sock,mode,dict.new(),200)
  let _ = close(sock)
 })
 let assert Ok(port) = process.receive(reply,1000)
 #(pid,port)
}
