fn applied(b: peers.Handle, attempts: Int) {
 let assert Ok(view) = peers.snapshot(b)
 let state = peer.engine_snapshot(view.peer)
 let present = list.any(state.local_mesh_state.active_workers.elements,fn(x) { x.0 == "worker-owned-live" })
 case present, list.key_find(state.local_health_map,"a") {
  True,Ok(health) if health.value.health_score == 0.91 -> True
  _,_ -> case attempts > 0 { True -> {process.sleep(50) applied(b,attempts - 1)} False -> False }
 }
}
fn readbacks(endpoint: http.Endpoint, run: String, sender: String, destination: String, count: Int) {
 int.range(1,count + 1,Nil,fn(_,seq) {
  let key = "uos/tui/state/ev98-peer/01a08017-fd72-7b20-9d32-4df53154bcc8/" <> run <> "/" <> sender <> "/" <> destination <> "/" <> int.to_string(seq)
  let assert Ok(response) = http.request(endpoint,http.Get,key,"",1000)
  io.println(json.object([#("kind",json.string("broker_readback")),#("key",json.string(key)),#("body",json.string(response.body))]) |> json.to_string)
 })
}
